// The scale cities of M3-20 (PRD, "Scale checkpoints"): each of 50,000,
// 200,000 and 500,000 residents, generated by the sim's
// `generateScaleCity`, given money as a player's city of that size has it
// since M4-20 (`furnishEconomy`: a treasury, tax rates off their defaults,
// City Hall and a loan), loaded from its bytes as a city file opens, and
// run for two game days with every system timed, the tax sweep and upkeep
// among them. Run with `pnpm bench`.
//
// It lives in the client because it reads a clock to time each system, as
// the host does through the sim's timer hook (CLAUDE.md rule 3 keeps the
// clock out of packages/sim, its tests included).
//
// For each city it records the pops, the buildings, the snapshot's size,
// how long the load takes (the bytes read and the derived data built), the
// mean and worst time of every system over the two days, and the worst
// tick. The table goes to the log, to the GitHub job summary when there is
// one, and to bench-results/scale-cities.md.
//
// The mean step is held to the tick (`cities.step` in the sim's
// budgets.json). A system's worst tick is one sample of 200, so it is
// shown against that system's share of the tick from its own figure and
// not held: the system's own bench holds it, on many runs. One over its
// share gets an issue (M3-20).

import { appendFileSync, mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { performance } from "node:perf_hooks";
import { expect, test } from "vitest";
import {
  ARRIVALS_SYSTEM,
  BUILDINGS_BALANCE,
  BUILDING_TYPES,
  COMMANDS_SYSTEM,
  LINE,
  DISPLACED_SYSTEM,
  DEMAND_SYSTEM,
  GROWER_SYSTEM,
  JOBS_SYSTEM,
  LAND_VALUE_SYSTEM,
  SATISFACTION_SYSTEM,
  SCALE_CITY_RESIDENTS,
  TAX_SYSTEM,
  TIME_BALANCE,
  TRAVEL_SYSTEM,
  TURNOVER_SYSTEM,
  UPKEEP_SYSTEM,
  VACANCY_SYSTEM,
  budgetFigure,
  blockBudgets,
  buildScaleCity,
  furnishEconomy,
  fundCity,
  buildingCount,
  buildingInfo,
  buildingPeople,
  compensationFor,
  formatMoneyFull,
  jobsFilled,
  planRoad,
  submit,
  terrainOf,
  travelTimesReady,
  deserialize,
  generateScaleCity,
  prepareDerived,
  serialize,
  step,
  type GeneratedScaleCity,
  type ScaleCity,
  type ScaleEconomy,
  type ScaleCityResidents,
  type SystemTimer,
} from "@city-council/sim";
import { holdDemandBars } from "../src/protocol/held-demand";
import { hold } from "./budget";
import { SimHost } from "../src/protocol/host";
import { memoryTransportPair } from "../src/protocol/transport";

/** Two game days. */
const TICKS = 2 * TIME_BALANCE.ticksPerDay;

/** Each system's share of the 20 ms tick: the budget of its own bench's figure in budgets.json. */
const SHARES: Readonly<Record<string, string>> = {
  [DEMAND_SYSTEM]: "demand.tick",
  [ARRIVALS_SYSTEM]: "arrivals.tick",
  [JOBS_SYSTEM]: "jobs.tick",
  [SATISFACTION_SYSTEM]: "satisfaction.tick",
  [TURNOVER_SYSTEM]: "turnover.tick",
  [VACANCY_SYSTEM]: "vacancy.tick",
  [LAND_VALUE_SYSTEM]: "landvalue.tick",
  [GROWER_SYSTEM]: "grower.share",
  [UPKEEP_SYSTEM]: "upkeep.tick",
  [TAX_SYSTEM]: "tax.tick",
};

interface SystemTimes {
  total: number;
  worst: number;
  /** The tick its worst time was on. */
  worstTick: number;
}

interface CityRun {
  residents: ScaleCityResidents;
  population: number;
  pops: number;
  buildings: number;
  snapshotBytes: number;
  generateMs: number;
  loadMs: number;
  stepMeanMs: number;
  worstStepMs: number;
  worstStepTick: number;
  systems: Map<string, SystemTimes>;
  endPopulation: number;
}

const round = (x: number, places = 2): number => Math.round(x * 10 ** places) / 10 ** places;
const mb = (bytes: number): number => round(bytes / 1024 / 1024, 1);

/** Runs a full collection, so the garbage of what came before is not collected inside a timed tick. The bench runs with --expose-gc. */
const collect = (): void => (globalThis as { gc?: () => void }).gc?.();

/** A generated city as a city file holds it, with what the generator reported and the money it was given. */
interface Generated {
  residents: ScaleCityResidents;
  bytes: Uint8Array;
  totals: GeneratedScaleCity["totals"];
  generateMs: number;
  economy: ScaleEconomy;
}

/** Generates the city of `residents` on a copy of the scale city, `shape` and the snapshot `base`, and gives it its money (M4-20). */
function generate(residents: ScaleCityResidents, shape: Omit<ScaleCity, "state">, base: Uint8Array): Generated {
  const t0 = performance.now();
  const city = generateScaleCity(residents, { ...shape, state: deserialize(base).state });
  const generateMs = performance.now() - t0;
  const economy = furnishEconomy(city.state, residents);
  return { residents, bytes: serialize(city.state), totals: city.totals, generateMs, economy };
}

/**
 * A game day on a copy of `city`, untimed, with every bar held at 100, so
 * the ticks timed after it are not the ones that compile the systems. The
 * bars are held so the grower adds buildings and pops move in and take
 * jobs on most of its ticks: a day at the city's own bars runs those paths
 * a few times or not at all, and the timed run then met them on its first
 * call. On the 500,000 city that put the grower's worst tick over its share
 * on the tick it first added a workplace, its pass over the workplaces 3.8
 * ms on the first call and 0.7 ms from the third (issue #354). That pass
 * is gone since #366, which found the engine threw its compiled code away
 * when the warm-up's city was collected; the day still compiles the rest.
 * Returns the buildings the day added.
 */
function warmUp(city: Generated): number {
  const state = deserialize(city.bytes).state;
  prepareDerived(state);
  const before = buildingCount(state.buildings);
  const letGo = holdDemandBars(100);
  try {
    for (let k = 0; k < TIME_BALANCE.ticksPerDay; k++) step(state);
  } finally {
    letGo();
  }
  return buildingCount(state.buildings) - before;
}

/** Loads `city` from its bytes as a city file opens and runs it for `ticks`, every system timed. */
function runCity(city: Generated, ticks = TICKS): CityRun {
  const { residents, bytes, totals, generateMs } = city;
  collect();
  // As a city file opens: the bytes read, then the derived data the host builds.
  const t0 = performance.now();
  const state = deserialize(bytes).state;
  prepareDerived(state);
  const loadMs = performance.now() - t0;
  collect();

  const systems = new Map<string, SystemTimes>();
  let started = 0;
  let stepMs = 0;
  const timer: SystemTimer = {
    start: () => void (started = performance.now()),
    end: (name) => {
      const ms = performance.now() - started;
      stepMs += ms;
      const s = systems.get(name) ?? { total: 0, worst: 0, worstTick: 0 };
      s.total += ms;
      if (ms > s.worst) {
        s.worst = ms;
        s.worstTick = state.tick;
      }
      systems.set(name, s);
    },
  };
  let total = 0;
  let worst = 0;
  let worstTick = 0;
  for (let k = 0; k < ticks; k++) {
    stepMs = 0;
    const tick = state.tick;
    step(state, timer);
    total += stepMs;
    if (stepMs > worst) {
      worst = stepMs;
      worstTick = tick;
    }
  }
  return {
    residents,
    population: totals.population,
    pops: totals.pops,
    buildings: totals.buildings,
    snapshotBytes: bytes.byteLength,
    generateMs,
    loadMs,
    stepMeanMs: total / ticks,
    worstStepMs: worst,
    worstStepTick: worstTick,
    systems,
    endPopulation: state.stats.totals["population"] ?? 0,
  };
}

/** Bytes of the typed arrays in `value` plus the JSON of the rest: about what a structured clone or a socket carries. */
function messageBytes(value: unknown): number {
  let typed = 0;
  const json = JSON.stringify(value, (_key, v: unknown) => {
    if (ArrayBuffer.isView(v)) {
      typed += v.byteLength;
      return 0;
    }
    return v;
  });
  return typed + json.length;
}

/** The M3 close-out's checkpoints on one city (M3-22): what the two-day run does not measure. */
interface Checkpoints {
  residents: ScaleCityResidents;
  /** The worker's time per tick over a game day, step and delta together, as the host runs them. */
  workerMeanMs: number;
  workerWorstMs: number;
  /** The worst tick's slowest system, outside the step when it is the delta or a collection. */
  workerWorstWhere: string;
  /** A game day's deltas, as the host sends them. */
  dayDeltaBytes: number;
  worstDeltaBytes: number;
  /** An autosave: the capture on the tick it starts, then each part written between ticks. */
  saveCaptureMs: number;
  savePartWorstMs: number;
  saveTotalMs: number;
  saveBytes: number;
  /** One BulldozeBuilding at its cap, every building in it occupied. */
  bulldozed: number;
  bulldozedPeople: number;
  bulldozeStepMs: number;
  bulldozeCommandMs: number;
  /** What it was charged at the eminent domain price (M4-09), whole dollars. */
  bulldozeCharged: number;
  /** The treasury the city was given, the loan it took and the treasury once it was charged the bulldoze (M4-20). */
  economy: ScaleEconomy;
  treasuryAfterBulldoze: number;
  /** The budget overlay's figures for every block and chunk, worked out from the city as the page's mirror does: the fastest and slowest of three (M4-18, M4-20). */
  overlayMs: [number, number];
  overlayAreas: number;
  /** The price of clearing the occupied house farthest from the centre, and of the occupied tower nearest it (M4-09). */
  edgeHousePrice: number;
  downtownTowerPrice: number;
  /** The worst tick, and the displaced pass's worst, over the game day after it. */
  afterBulldozeWorstMs: number;
  displacedWorstMs: number;
  /** The satisfaction system's worst tick over that day, with the clearing's 1,000 records fresh (M4-10). */
  satisfactionAfterWorstMs: number;
  /** The travel table's rebuild after one BuildRoad. */
  travelSteps: number;
  travelTotalMs: number;
  travelWorstMs: number;
  travelWorstStepMs: number;
  /** Which step of the rebuild the worst tick was, the step that applies the command being 0, and its slowest system (#453). */
  travelWorstWhere: string;
}

/** A street a quarter of the way into a row of one of the city's grids, crossing several of its streets. */
function crossing(state: ScaleCity["state"], grids: ScaleCity["grids"]): unknown {
  const terrain = terrainOf(state.seed);
  for (const g of grids) {
    const z = g.z + 24;
    const payload = { from: { x: g.x - 24, z }, to: { x: g.x + 6 * 96, z }, type: "street" };
    if (planRoad(state.roads, terrain, payload).ok) return payload;
  }
  throw new Error("no street fits across a grid");
}

/** Opens `city` in a host as the worker does and takes the close-out's checkpoints on it. */
function checkpoints(city: Generated, grids: ScaleCity["grids"]): Checkpoints {
  collect();
  const state = deserialize(city.bytes).state;
  const { client, host: hostEnd } = memoryTransportPair();
  const host = new SimHost(state, hostEnd, () => performance.now());
  // Each delta's size and the per-system timings of the step before it.
  let deltaBytes = 0;
  let worstDelta = 0;
  let timings: { system: string; ms: number }[] = [];
  // The in-memory transport delivers inside `advance`, so a delta is only kept here and measured after the tick's time is taken.
  const sent: unknown[] = [];
  client.onMessage((m) => {
    if (m.type !== "delta") return;
    sent.push(m);
    timings = m.timings;
  });
  const measureSent = (): void => {
    for (const m of sent) {
      const bytes = messageBytes(m);
      deltaBytes += bytes;
      worstDelta = Math.max(worstDelta, bytes);
    }
    sent.length = 0;
  };
  let seq = 1;
  const send = (type: string, payload: unknown): void => {
    const result = submit(state, { seq: seq++, playerId: "bench", type, payload });
    if (!result.ok) throw new Error(`${type}: ${result.reason}`);
  };
  const tick = (): { ms: number; timings: { system: string; ms: number }[] } => {
    const t0 = performance.now();
    host.advance(1);
    const ms = performance.now() - t0;
    measureSent();
    return { ms, timings };
  };
  const systemMs = (t: { system: string; ms: number }[], name: string): number => t.filter((x) => x.system === name).reduce((n, x) => n + x.ms, 0);

  /** Where a tick's time went: its slowest system and all it stepped. */
  const where = (t: { timings: { system: string; ms: number }[] }): string => {
    const top = [...t.timings].sort((p, q) => q.ms - p.ms)[0];
    const stepped = t.timings.reduce((n, x) => n + x.ms, 0);
    return `${top?.system ?? "-"} ${round(top?.ms ?? 0)} ms of ${round(stepped)} ms stepped`;
  };

  // A game day as the worker runs it, after a tick that compiles the host's code.
  tick();
  deltaBytes = 0;
  worstDelta = 0;
  let workerTotal = 0;
  let workerWorst = 0;
  let workerWorstWhere = "";
  for (let k = 0; k < TIME_BALANCE.ticksPerDay; k++) {
    const at = state.tick;
    const t = tick();
    workerTotal += t.ms;
    if (t.ms > workerWorst) {
      workerWorst = t.ms;
      workerWorstWhere = `tick ${at}: ${where(t)}`;
    }
  }
  const dayDeltaBytes = deltaBytes;
  const worstDeltaBytes = worstDelta;

  // An autosave, as the worker writes one: captured on a tick, then a part between ticks.
  collect();
  const s0 = performance.now();
  const pending = host.startSave(0);
  const saveCaptureMs = performance.now() - s0;
  let savePartWorstMs = 0;
  let part: IteratorResult<undefined, Uint8Array>;
  do {
    const p0 = performance.now();
    part = pending.steps.next();
    savePartWorstMs = Math.max(savePartWorstMs, performance.now() - p0);
  } while (!part.done);
  const saveBytes = part.value.byteLength;
  const saveTotalMs = performance.now() - s0;
  pending.release();

  // The budget overlay's figures, as the mirror works them out when the overlay is on.
  const overlayRuns: number[] = [];
  let overlayAreas = 0;
  for (let k = 0; k < 3; k++) {
    collect();
    const o0 = performance.now();
    const figures = blockBudgets(state);
    overlayRuns.push(performance.now() - o0);
    overlayAreas = figures.blocks.length + figures.chunkTax.length;
  }

  // A house at the edge against a tower downtown: value follows land value and floor space (M4-09).
  const b = state.buildings;
  const people = (id: number) => buildingPeople(state, id);
  const filled = (id: number) => jobsFilled(state, id);
  // How far its lot's corners lie from the city centre, on average.
  const centreOf = (id: number): number => {
    const c = buildingInfo(state, id)?.corners;
    if (!c) return 0;
    const at = (i: number): number => c[i] ?? 0;
    const cx = (at(0) + at(2) + at(4) + at(6)) / 4;
    const cz = (at(1) + at(3) + at(5) + at(7)) / 4;
    return Math.hypot(cx - state.centre.x, cz - state.centre.z);
  };
  let edgeHouse = -1;
  let edgeDistance = -1;
  let tower = -1;
  let towerDistance = Infinity;
  for (let id = 0; id < b.flags.length; id++) {
    if (!b.flags[id] || people(id) === 0) continue;
    const type = BUILDING_TYPES[b.type[id] ?? 0];
    if (type?.oneHousehold) {
      const d = centreOf(id);
      if (d > edgeDistance) [edgeHouse, edgeDistance] = [id, d];
    } else if (type?.zone === "residential" && type.density === 3) {
      const d = centreOf(id);
      if (d < towerDistance) [tower, towerDistance] = [id, d];
    }
  }
  const priceOf = (id: number): number => (id < 0 ? 0 : compensationFor(state, [id], people, filled).total);
  const edgeHousePrice = priceOf(edgeHouse);
  const downtownTowerPrice = priceOf(tower);

  // One BulldozeBuilding at its cap, over occupied buildings only.
  const chosen: { id: number; segment: number; side: number; place: number; builtAt: number }[] = [];
  let bulldozedPeople = 0;
  for (let id = 0; id < b.flags.length && chosen.length < BUILDINGS_BALANCE.bulldozeMaxBuildings; id++) {
    if (!b.flags[id]) continue;
    const people = buildingPeople(state, id);
    if (people === 0) continue;
    bulldozedPeople += people;
    chosen.push({ id, segment: b.firstSeg[id] ?? 0, side: b.firstSide[id] ?? 0, place: b.firstPlace[id] ?? 0, builtAt: b.builtAt[id] ?? 0 });
  }
  // Its compensation on top of the treasury, so the overdraft does not refuse it: at the
  // eminent domain price a thousand occupied buildings cost more than a few years of
  // the city's tax. A city that clears so much at once saves for it first.
  const price = compensationFor(state, chosen.map((c) => c.id), people, filled).total;
  fundCity(state, state.budget.treasury + price);
  collect();
  send("BulldozeBuilding", { buildings: chosen });
  const compensationBefore = state.budget.month[LINE.compensation] ?? 0;
  const bulldoze = tick();
  // Read off the line, which only the bulldoze moves: taxes and upkeep move the treasury on the same tick.
  const bulldozeCharged = (state.budget.month[LINE.compensation] ?? 0) - compensationBefore;
  const treasuryAfterBulldoze = state.budget.treasury;
  let afterBulldozeWorstMs = 0;
  let displacedWorstMs = systemMs(bulldoze.timings, DISPLACED_SYSTEM);
  let satisfactionAfterWorstMs = systemMs(bulldoze.timings, SATISFACTION_SYSTEM);
  for (let k = 0; k < TIME_BALANCE.ticksPerDay; k++) {
    const t = tick();
    afterBulldozeWorstMs = Math.max(afterBulldozeWorstMs, t.ms);
    displacedWorstMs = Math.max(displacedWorstMs, systemMs(t.timings, DISPLACED_SYSTEM));
    satisfactionAfterWorstMs = Math.max(satisfactionAfterWorstMs, systemMs(t.timings, SATISFACTION_SYSTEM));
  }

  // One BuildRoad, and the steps until its travel table is whole.
  while (!travelTimesReady(state)) tick();
  collect();
  send("BuildRoad", crossing(state, grids));
  let travelSteps = 0;
  let travelTotalMs = 0;
  let travelWorstMs = 0;
  let travelWorstStepMs = 0;
  let travelWorstWhere = "";
  do {
    const t = tick();
    const ms = systemMs(t.timings, TRAVEL_SYSTEM);
    travelTotalMs += ms;
    travelWorstMs = Math.max(travelWorstMs, ms);
    if (t.ms > travelWorstStepMs) {
      travelWorstStepMs = t.ms;
      travelWorstWhere = `step ${travelSteps}: ${where(t)}`;
    }
    travelSteps++;
  } while (!travelTimesReady(state));

  return {
    residents: city.residents,
    workerMeanMs: workerTotal / TIME_BALANCE.ticksPerDay,
    workerWorstMs: workerWorst,
    workerWorstWhere,
    dayDeltaBytes,
    worstDeltaBytes,
    saveCaptureMs,
    savePartWorstMs,
    saveTotalMs,
    saveBytes,
    bulldozed: chosen.length,
    bulldozedPeople,
    bulldozeStepMs: bulldoze.ms,
    bulldozeCommandMs: systemMs(bulldoze.timings, COMMANDS_SYSTEM),
    bulldozeCharged,
    economy: city.economy,
    treasuryAfterBulldoze,
    overlayMs: [Math.min(...overlayRuns), Math.max(...overlayRuns)],
    overlayAreas,
    edgeHousePrice,
    downtownTowerPrice,
    afterBulldozeWorstMs,
    displacedWorstMs,
    satisfactionAfterWorstMs,
    travelSteps,
    travelTotalMs,
    travelWorstMs,
    travelWorstStepMs,
    travelWorstWhere,
  };
}

function checkpointTable(rows: readonly Checkpoints[]): string {
  const row = (label: string, cells: string[]) => `| ${label} | ${cells.join(" | ")} |`;
  const kb = (bytes: number): string => `${Math.round(bytes / 1024).toLocaleString("en")} KB`;
  const ms = (v: number): string => `${round(v)}`;
  return `${[
    "### Scale cities: the close-out's checkpoints (M3-22, with money since M4-20)",
    "",
    "In a host as the worker runs it, over an in-memory transport. The 20 ms tick is the budget for a worker tick.",
    "",
    row("", rows.map((r) => r.residents.toLocaleString("en"))),
    `|---|${rows.map(() => "---:").join("|")}|`,
    row("Worker tick over a game day, mean ms", rows.map((r) => ms(r.workerMeanMs))),
    row("Worker tick over a game day, worst ms", rows.map((r) => ms(r.workerWorstMs))),
    row("The worst tick's slowest system", rows.map((r) => r.workerWorstWhere)),
    row("Treasury given, loan taken (M4-20)", rows.map((r) => `${formatMoneyFull(r.economy.treasury)}, ${formatMoneyFull(r.economy.loan)}`)),
    row("Budget overlay figures, fastest and slowest of three, ms", rows.map((r) => `${ms(r.overlayMs[0])}, ${ms(r.overlayMs[1])} (${r.overlayAreas.toLocaleString("en")} areas)`)),
    row("A game day's deltas", rows.map((r) => kb(r.dayDeltaBytes))),
    row("Largest delta", rows.map((r) => kb(r.worstDeltaBytes))),
    row("Autosave: capture on its tick, ms", rows.map((r) => ms(r.saveCaptureMs))),
    row("Autosave: worst part between ticks, ms", rows.map((r) => ms(r.savePartWorstMs))),
    row("Autosave: all parts, ms", rows.map((r) => ms(r.saveTotalMs))),
    row("Autosave: bytes", rows.map((r) => `${mb(r.saveBytes)} MB`)),
    row("BulldozeBuilding: buildings, people in them", rows.map((r) => `${r.bulldozed.toLocaleString("en")}, ${r.bulldozedPeople.toLocaleString("en")}`)),
    row("BulldozeBuilding: the tick that applies it, ms", rows.map((r) => ms(r.bulldozeStepMs))),
    row("BulldozeBuilding: its command, ms", rows.map((r) => ms(r.bulldozeCommandMs))),
    row("BulldozeBuilding: charged at the eminent domain price", rows.map((r) => formatMoneyFull(r.bulldozeCharged))),
    row("BulldozeBuilding: the treasury after it", rows.map((r) => formatMoneyFull(r.treasuryAfterBulldoze))),
    row("Clearing the occupied house farthest from the centre", rows.map((r) => formatMoneyFull(r.edgeHousePrice))),
    row("Clearing the occupied tower nearest the centre", rows.map((r) => formatMoneyFull(r.downtownTowerPrice))),
    row("The game day after: worst tick, ms", rows.map((r) => ms(r.afterBulldozeWorstMs))),
    row("The game day after: worst displaced pass, ms", rows.map((r) => ms(r.displacedWorstMs))),
    row(`The game day after: worst satisfaction tick, ms (share ${budgetFigure(SHARES[SATISFACTION_SYSTEM] as string).budget})`, rows.map((r) => ms(r.satisfactionAfterWorstMs))),
    row("Travel rebuild after one BuildRoad: steps", rows.map((r) => `${r.travelSteps}`)),
    row("Travel rebuild: all steps, ms", rows.map((r) => ms(r.travelTotalMs))),
    row("Travel rebuild: worst step's travel, ms", rows.map((r) => ms(r.travelWorstMs))),
    row("Travel rebuild: worst tick, ms", rows.map((r) => ms(r.travelWorstStepMs))),
    row("Travel rebuild: the worst tick's step, 0 the one that applies the BuildRoad, and its slowest system", rows.map((r) => r.travelWorstWhere)),
  ].join("\n")}\n`;
}

function table(runs: readonly CityRun[]): string {
  const names = [...new Set(runs.flatMap((r) => [...r.systems.keys()]))];
  const head = ["", ...runs.map((r) => `${r.residents.toLocaleString("en")}`)];
  const row = (label: string, cells: string[]) => `| ${label} | ${cells.join(" | ")} |`;
  const lines = [
    `### Scale cities: two game days each (${TICKS} ticks)`,
    "",
    row(head[0] ?? "", head.slice(1)),
    `|---|${runs.map(() => "---:").join("|")}|`,
    row("Population", runs.map((r) => r.population.toLocaleString("en"))),
    row("Population after two days", runs.map((r) => r.endPopulation.toLocaleString("en"))),
    row("Pops", runs.map((r) => r.pops.toLocaleString("en"))),
    row("Buildings", runs.map((r) => r.buildings.toLocaleString("en"))),
    row("Snapshot", runs.map((r) => `${mb(r.snapshotBytes)} MB`)),
    row("Generate, ms", runs.map((r) => `${Math.round(r.generateMs)}`)),
    row("Load (read and derive), ms", runs.map((r) => `${Math.round(r.loadMs)}`)),
    row("Step, mean ms", runs.map((r) => `${round(r.stepMeanMs)}`)),
    row("Worst tick, ms", runs.map((r) => `${round(r.worstStepMs)} (tick ${r.worstStepTick})`)),
    "",
    "Each system's mean / worst ms over the two days, and the tick of its worst, against its share of the 20 ms tick where it has one. **Over** marks a worst past its share.",
    "",
    row("System", [...runs.map((r) => `${r.residents.toLocaleString("en")}`), "Share, ms"]),
    `|---|${runs.map(() => "---:").join("|")}|---:|`,
  ];
  for (const name of names) {
    const share = SHARES[name] ? budgetFigure(SHARES[name]).budget : null;
    const cells = runs.map((r) => {
      const s = r.systems.get(name);
      if (!s) return "";
      const over = share !== null && s.worst > share ? " **over**" : "";
      return `${round(s.total / TICKS, 3)} / ${round(s.worst)} (tick ${s.worstTick})${over}`;
    });
    lines.push(row(name, [...cells, share === null ? "" : `${share}`]));
  }
  return `${lines.join("\n")}\n`;
}

/**
 * The scale city's shape and snapshot, without its state. Built by stepping,
 * that state is still walking a change of roads whose queue holds over a
 * million objects. Held for the whole test, it was half the heap, and a
 * collection that landed in a timed tick of the 500,000 city took 260 to
 * 330 ms where the worker's own heap takes 5 to 15 (issue #355).
 */
function scaleCityBase(): { shape: Omit<ScaleCity, "state">; base: Uint8Array } {
  const { state, ...shape } = buildScaleCity();
  return { shape, base: serialize(state) };
}

test("the scale cities, two game days each", () => {
  const { shape, base } = scaleCityBase();
  const cities = SCALE_CITY_RESIDENTS.map((residents) => generate(residents, shape, base));
  // A day on a copy of the first, untimed, so no city's ticks are the ones that compile the systems.
  const warmed = warmUp(cities[0] as Generated);
  console.log(`The warm-up day added ${warmed} buildings.`);
  expect(warmed, "the warm-up day added no buildings, so it compiled none of the grower's building paths").toBeGreaterThan(0);
  const runs = cities.map((city) => runCity(city));
  for (const run of runs) {
    // `cities.step` in the sim's budgets.json: the mean step inside the tick.
    hold("cities.step", `a step on the scale city of ${run.residents.toLocaleString("en")}`, { mean: run.stepMeanMs, max: run.worstStepMs });
    expect(run.population).toBeGreaterThan(0);
  }
  // The close-out's checkpoints (M3-22), recorded and not held: the systems' own benches hold their budgets.
  const points = cities.map((city) => checkpoints(city, shape.grids));
  // Every clear is at the cap: each city has more occupied buildings than it.
  for (const p of points) expect(p.bulldozed).toBe(BUILDINGS_BALANCE.bulldozeMaxBuildings);
  const text = `${table(runs)}\n${checkpointTable(points)}`;
  console.log(text);
  mkdirSync("bench-results", { recursive: true });
  writeFileSync(join("bench-results", "scale-cities.md"), text);
  const summary = process.env["GITHUB_STEP_SUMMARY"];
  if (summary) appendFileSync(summary, `${text}\n`);
}, 1_800_000);
